                    // i is the client that just received a response, so it's now idle
                    assert(post.clients.index(i).is_Idle());
                    assert(!post.slots.index(i)); // Slot was set to false in transition
                } else {
                    // For other indices, the state hasn't changed
                    assert(pre.clients.index(i) == post.clients.index(i));
                    assert(pre.slots.index(i) == post.slots.index(i));
                    // Since pre satisfies the invariant, we have the result
                    assert(pre.valid_idx(i) && pre.clients.index(i).is_Idle() ==> !pre.slots.index(i));
                }
            }

            // Proof that waiting_inv holds
            assert forall |i: nat| #[trigger] post.client_waiting(i) implies
                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)
            by {
                if i == j {
                    // i is the client that just received a response, so it's not waiting anymore
                    assert(!post.client_waiting(i));
                } else {
                    // For other indices, the state hasn't changed
                    assert(pre.client_waiting(i) == post.client_waiting(i));
                    assert(pre.request_stored(i) == post.request_stored(i));
                    assert(pre.response_stored(i) == post.response_stored(i));
                    assert(pre.combiner_has(i) == post.combiner_has(i));
                    // Since pre satisfies the invariant, we have the result
                }
            }

            // Proof that response_stored_inv holds
            assert forall |i: nat| #[trigger] post.response_stored(i) implies
                post.client_waiting(i)
                && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
                && !post.slots.index(i)
            by {
                if i == j {
                    // i is the response we just withdrew, so it's no longer stored
                    assert(!post.response_stored(i));
                } else {
                    // For other indices, the state hasn't changed
                    assert(pre.response_stored(i) == post.response_stored(i));
