                    assert(post.combiner_rid(j) == request.rid);
                    // Since clients didn't change:
                    assert(post.clients.index(j).get_Waiting_rid() == pre.clients.index(j).get_Waiting_rid());
                    assert(post.combiner_rid(j) == post.clients.index(j).get_Waiting_rid());
                    assert(!post.request_stored(j)); // We just withdrew it
                } else {
                    // For other indices, the state hasn't changed
                    assert(pre.combiner_has(i) == post.combiner_has(i));
                    // Since pre satisfies the invariant, we have the result
                }
            }
        }

        transition!{
            combiner_skip() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // In practice, this happens when slot j is set to false, so we could add this:
                //    have slots >= [j => false];
                // but it's not necessary

